//! The Object part of Region dumps, checked against the C library.
//!
//! `region_object_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/region_object_probe.c`. A Region keeps its own
//! Ident, written before the Frame proxy (object.c `Dump`), while UseDefs
//! set through it goes to the encapsulated Frame and is written in that
//! Frame's dump (region.c `SetAttrib`, `GetUseDefs`).

use crate::common::native_dump;
#[path = "region_object_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrame, BasicFrameBuilder, Frame};
use starlink_ast::regions::{
    BoxRegionBuilder, CircleBuilder, CmpOperator, CmpRegionBuilder, IntervalBuilder, PolygonBuilder,
};
use starlink_ast::{AnyObject, from_native_string};

fn frame() -> BasicFrame {
    BasicFrameBuilder::new(2).build().unwrap()
}

fn with<F: Frame>(mut f: F, ident: Option<&str>, use_defs: Option<bool>) -> F {
    if let Some(i) = ident {
        f.set_ident(i).unwrap();
    }
    if let Some(u) = use_defs {
        f.set_use_defs(u).unwrap();
    }
    f
}

fn circle() -> starlink_ast::regions::Circle {
    CircleBuilder::new(frame(), vec![0.0, 0.0])
        .unwrap()
        .radius(1.0)
        .build()
        .unwrap()
}

fn boxr() -> starlink_ast::regions::BoxRegion {
    BoxRegionBuilder::new(frame(), vec![0.0, 0.0], vec![1.0, 2.0])
        .unwrap()
        .build()
        .unwrap()
}

fn build(name: &str) -> AnyObject {
    match name {
        "circle_ident_usedefs" => AnyObject::Circle(with(circle(), Some("Circ"), Some(false))),
        "box_ident" => AnyObject::BoxRegion(with(boxr(), Some("B"), None)),
        "interval_usedefs" => AnyObject::Interval(with(
            IntervalBuilder::new(frame(), vec![-1.0, -2.0], vec![1.0, 2.0])
                .unwrap()
                .build()
                .unwrap(),
            None,
            Some(false),
        )),
        "polygon_ident" => AnyObject::Polygon(with(
            PolygonBuilder::new(
                frame(),
                vec![vec![0.0, 0.0], vec![1.0, 0.0], vec![0.0, 1.0]],
            )
            .unwrap()
            .build()
            .unwrap(),
            Some("P"),
            None,
        )),
        "cmpregion_idents" => AnyObject::CmpRegion(with(
            CmpRegionBuilder::new(
                with(circle(), Some("A"), None),
                with(boxr(), Some("B"), None),
                CmpOperator::Or,
            )
            .unwrap()
            .build()
            .unwrap(),
            Some("AB"),
            None,
        )),
        "circle_plain" => AnyObject::Circle(circle()),
        other => panic!("no Rust set-up for {other}"),
    }
}

#[test]
fn region_object_parts_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, ident, use_defs, set, dump) in cases::CASES {
        let obj = build(name);
        let f = obj.as_frame().expect("a Frame");
        let got = (f.ident().to_string(), f.use_defs(), f.test_use_defs());
        if got != (ident.to_string(), use_defs, set) {
            failures.push(format!(
                "{name}: got {got:?}, C gives {:?}",
                (ident, use_defs, set)
            ));
        }
        let written = native_dump(&obj).unwrap();
        if written != dump {
            failures.push(format!("{name}: dump differs\n{written}\nC:\n{dump}"));
        }
        let read = from_native_string(dump).unwrap();
        let back = read.as_frame().expect("a Frame");
        if (
            back.ident().to_string(),
            back.use_defs(),
            back.test_use_defs(),
        ) != (ident.to_string(), use_defs, set)
        {
            failures.push(format!("{name}: read back differently"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
